import{at as e,it as t,n,vt as r}from"./chunks/framework.D9OOHiq-.js";var i=JSON.parse(`{"title":"配置详解","description":"","frontmatter":{},"headers":[],"relativePath":"modules/dungeon/configuration.md","filePath":"modules/dungeon/configuration.md","lastUpdated":0}`),a={name:`modules/dungeon/configuration.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="配置详解" tabindex="-1">配置详解 <a class="header-anchor" href="#配置详解" aria-label="Permalink to “配置详解”">​</a></h1><p>EmakiDungeon 一共有三份配置: 全局主配置 <code>plugins/EmakiDungeon/config.yml</code>, 每个副本自己的 <code>plugins/EmakiDungeon/world/&lt;副本ID&gt;/config.yml</code>, 以及奖励箱界面 <code>plugins/EmakiDungeon/gui/rewardbox.yml</code>. 你改完执行 <code>/edg admin reload</code> 即可生效 (这条命令由有 <code>emakidungeon.admin</code> 权限的玩家执行), 运行中的实例不受影响, 只对之后新建的实例生效</p><p>文件顶部的 <code>version</code> 与 <code>language</code> 由资源同步流程维护, 你不要手动改. 副本级配置<strong>没有 schema 兼容层</strong>, 加载期会按当前结构严格校验; 下表&quot;取值范围&quot;列里标注了源码校验的键, <strong>未标注 <code>—</code> 的键都以源码校验为准</strong>, 校验分两种:</p><ul><li><strong>直接报错</strong> (该副本被跳过, 控制台报&quot;副本配置非法&quot;): <code>pool.max-worlds</code>, <code>enter.prepare-window-seconds</code>, <code>enter.wait-timeout-seconds</code>, <code>enter.wait-channel</code>, <code>limits.daily.time-window</code> 格式, <code>limits</code> 里的 <code>days</code>/<code>weeks</code> 条目</li><li><strong>静默回退</strong>: 插件把非法值剔除, 夹到边界或按默认值继续跑 (见各键说明)</li></ul><h2 id="全局主配置-config-yml" tabindex="-1">全局主配置 <code>config.yml</code> <a class="header-anchor" href="#全局主配置-config-yml" aria-label="Permalink to “全局主配置 config.yml”">​</a></h2><h3 id="debug-调试日志" tabindex="-1"><code>debug</code> 调试日志 <a class="header-anchor" href="#debug-调试日志" aria-label="Permalink to “debug 调试日志”">​</a></h3><table tabindex="0"><thead><tr><th>字段</th><th>类型</th><th>默认值</th><th>取值范围</th><th>说明</th></tr></thead><tbody><tr><td><code>debug.enabled</code></td><td>boolean</td><td><code>false</code></td><td><code>true</code> / <code>false</code></td><td>DEBUG 锚日志开关, 打开后控制台输出实例, 队伍, 次数等详细事件</td></tr><tr><td><code>debug.retention-days</code></td><td>int</td><td><code>30</code></td><td><code>—</code></td><td>审计与调试日志按天保留多久, 到期自动清理</td></tr></tbody></table><h3 id="limit-与-commands-全局限流" tabindex="-1"><code>limit</code> 与 <code>commands</code> 全局限流 <a class="header-anchor" href="#limit-与-commands-全局限流" aria-label="Permalink to “limit 与 commands 全局限流”">​</a></h3><table tabindex="0"><thead><tr><th>字段</th><th>类型</th><th>默认值</th><th>取值范围</th><th>说明</th></tr></thead><tbody><tr><td><code>limit.max-instances</code></td><td>int</td><td><code>20</code></td><td><code>—</code></td><td>全局并发实例世界上限 (含还没人进的补位世界), 达限后新的挑战直接拒绝</td></tr><tr><td><code>commands.mode</code></td><td>string</td><td><code>blacklist</code></td><td><code>blacklist</code> / <code>whitelist</code></td><td>副本内命令过滤模式: 黑名单只拦 <code>commands.rules</code> 列出的命令, 白名单只放行列出的命令</td></tr><tr><td><code>commands.rules</code></td><td>list&lt;string&gt;</td><td><code>[]</code></td><td>见说明</td><td>规则 = 命令根 + 参数模式, 例如 <code>&quot;/tpa player&quot;</code>, 玩家名位置统一写 <code>player</code> 占位</td></tr><tr><td><code>escape.blacklist</code></td><td>list&lt;string&gt;</td><td><code>[]</code></td><td>支持 <code>*</code> 通配符</td><td>逃逸命令黑名单 (例如 <code>&quot;/tp *&quot;</code>, <code>&quot;/back&quot;</code>), 判定优先级最高, <strong>任何放行条目都无法豁免</strong></td></tr></tbody></table><h3 id="party-与-isolation-组队社交" tabindex="-1"><code>party</code> 与 <code>isolation</code> 组队社交 <a class="header-anchor" href="#party-与-isolation-组队社交" aria-label="Permalink to “party 与 isolation 组队社交”">​</a></h3><table tabindex="0"><thead><tr><th>字段</th><th>类型</th><th>默认值</th><th>取值范围</th><th>说明</th></tr></thead><tbody><tr><td><code>party.max-size</code></td><td>int</td><td><code>4</code></td><td><code>—</code></td><td>一支队伍的人数上限</td></tr><tr><td><code>party.invite-mode</code></td><td>string</td><td><code>public</code></td><td><code>public</code> / <code>apply</code> / <code>invite</code></td><td>没队伍的玩家向别人发起加入时: <code>public</code> 直接进, <code>apply</code> 提交申请等批准, <code>invite</code> 仅被邀请者可进 (其他值按 <code>invite</code> 处理)</td></tr><tr><td><code>isolation.global-chat-default</code></td><td>boolean</td><td><code>false</code></td><td><code>true</code> / <code>false</code></td><td>新玩家默认是否全局收听; 玩家可用 <code>/edg globalchat</code> 随时切换</td></tr></tbody></table><h3 id="general-与-rewardbox-基础项" tabindex="-1"><code>general</code> 与 <code>rewardbox</code> 基础项 <a class="header-anchor" href="#general-与-rewardbox-基础项" aria-label="Permalink to “general 与 rewardbox 基础项”">​</a></h3><table tabindex="0"><thead><tr><th>字段</th><th>类型</th><th>默认值</th><th>取值范围</th><th>说明</th></tr></thead><tbody><tr><td><code>general.timezone</code></td><td>string</td><td><code>&quot;&quot;</code></td><td>留空或时区名</td><td>次数限制的默认时区, 留空用服务器时区</td></tr><tr><td><code>rewardbox.enabled</code></td><td>boolean</td><td><code>true</code></td><td><code>true</code> / <code>false</code></td><td>奖励箱总开关; 关闭后副本产出直接进背包, 背包满则落地为可拾取掉落物</td></tr></tbody></table><h3 id="script-graaljs-脚本宿主" tabindex="-1"><code>script</code> GraalJS 脚本宿主 <a class="header-anchor" href="#script-graaljs-脚本宿主" aria-label="Permalink to “script GraalJS 脚本宿主”">​</a></h3><table tabindex="0"><thead><tr><th>字段</th><th>类型</th><th>默认值</th><th>取值范围</th><th>说明</th></tr></thead><tbody><tr><td><code>script.enabled</code></td><td>boolean</td><td><code>true</code></td><td><code>true</code> / <code>false</code></td><td>是否随实例启动装载 <code>scripts/&lt;副本ID&gt;.js</code>; 关闭后脚本功能整体停用</td></tr><tr><td><code>script.timeout-ms</code></td><td>int</td><td><code>5000</code></td><td><code>—</code></td><td>单段脚本处理器的超时上限 (毫秒), 超时该脚本停用但实例继续</td></tr><tr><td><code>script.fail-on-error</code></td><td>boolean</td><td><code>false</code></td><td><code>true</code> / <code>false</code></td><td>脚本异常时是否判定本局副本失败; <code>false</code> 只停用脚本, 其余流程照常</td></tr></tbody></table><h3 id="monitor-运行告警" tabindex="-1"><code>monitor</code> 运行告警 <a class="header-anchor" href="#monitor-运行告警" aria-label="Permalink to “monitor 运行告警”">​</a></h3><table tabindex="0"><thead><tr><th>字段</th><th>类型</th><th>默认值</th><th>取值范围</th><th>说明</th></tr></thead><tbody><tr><td><code>monitor.mspt-p95-ms</code></td><td>int</td><td><code>55</code></td><td><code>&gt; 0</code> 或 <code>&lt;= 0</code> 关闭</td><td>稳态 MSPT P95 超过该值时控制台告警并写入审计日志</td></tr><tr><td><code>monitor.mspt-p95-enter-ms</code></td><td>int</td><td><code>200</code></td><td><code>&gt; 0</code> 或 <code>&lt;= 0</code> 关闭</td><td>进入/准备阶段专用 MSPT P95 阈值: 自挑战进入流程标记点 (世界获取/等待/入本完成) 起 65 秒内按此值判定, 期间超阈同样告警并写审计; 其余时间回退 <code>monitor.mspt-p95-ms</code></td></tr><tr><td><code>monitor.memory-slope-mb-per-min</code></td><td>int</td><td><code>64</code></td><td><code>&gt; 0</code> 或 <code>&lt;= 0</code> 关闭</td><td>堆内存斜率 (MB/分钟) 告警阈值</td></tr><tr><td><code>monitor.queue-backlog-seconds</code></td><td>int</td><td><code>5</code></td><td><code>&gt; 0</code> 或 <code>&lt;= 0</code> 关闭</td><td>写队列持续积压 (秒) 告警阈值</td></tr></tbody></table><h3 id="storage-folia-action" tabindex="-1"><code>storage</code> / <code>folia</code> / <code>action</code> <a class="header-anchor" href="#storage-folia-action" aria-label="Permalink to “storage / folia / action”">​</a></h3><table tabindex="0"><thead><tr><th>字段</th><th>类型</th><th>默认值</th><th>取值范围</th><th>说明</th></tr></thead><tbody><tr><td><code>storage.bstats</code></td><td>string</td><td><code>disabled</code></td><td>目前仅 <code>disabled</code></td><td>bStats 本期不接入, 接口就绪后经 CoreLib 统一接入</td></tr><tr><td><code>folia.held-worlds-max</code></td><td>int</td><td><code>10</code></td><td><code>—</code></td><td>Folia 上挂起世界的全局上限, 达限时按满载拒绝新挑战, 重启回收</td></tr><tr><td><code>action.&lt;段id&gt;</code></td><td>map</td><td><code>{}</code></td><td>动作管道行列表</td><td>副本生命周期动作, 段 id 即键名, 值为 CoreLib 动作管道配置</td></tr></tbody></table><p><code>action</code> 支持的段 id 共 11 个: <code>dungeon_enter</code>, <code>dungeon_exit</code>, <code>dungeon_room_clear</code>, <code>dungeon_gate_open</code>, <code>dungeon_wave_start</code>, <code>dungeon_score</code>, <code>dungeon_complete</code>, <code>dungeon_fail</code>, <code>dungeon_reward</code>, <code>dungeon_ending</code>, <code>dungeon_destroy</code>. 写法与 <a href="./../corelib/actions.html">CoreLib 动作系统</a> 相同, 例如:</p><div class="language-yaml" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">action</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">  dungeon_enter</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | send_message text=&quot;&lt;green&gt;进入副本&lt;/green&gt;&quot;&#39;</span></span></code></pre></div><h2 id="副本级配置-world-副本id-config-yml" tabindex="-1">副本级配置 <code>world/&lt;副本ID&gt;/config.yml</code> <a class="header-anchor" href="#副本级配置-world-副本id-config-yml" aria-label="Permalink to “副本级配置 world/&lt;副本ID&gt;/config.yml”">​</a></h2><p>此文件缺失时, 插件会在启动或重载时按内置模板自动生成; 已存在的文件不会被覆盖</p><h3 id="元数据与进入" tabindex="-1">元数据与进入 <a class="header-anchor" href="#元数据与进入" aria-label="Permalink to “元数据与进入”">​</a></h3><table tabindex="0"><thead><tr><th>字段</th><th>类型</th><th>默认值</th><th>取值范围</th><th>说明</th></tr></thead><tbody><tr><td><code>display-name</code></td><td>string</td><td><code>示例副本</code></td><td>任意文本</td><td>副本展示名, 出现在列表与消息里</td></tr><tr><td><code>description</code></td><td>string</td><td><code>一份用于演示的线性副本配置</code></td><td>任意文本</td><td>副本描述</td></tr><tr><td><code>difficulty-group</code></td><td>string</td><td><code>default</code></td><td>任意标识</td><td>难度分组标识</td></tr><tr><td><code>enter.timeout-seconds</code></td><td>int</td><td><code>1800</code></td><td><code>—</code></td><td>单局最长时限 (秒), 到点判本局失败: 触发 <code>DungeonFailEvent</code> (TIMEOUT), <strong>补走失败结算</strong> (审计 <code>[settle]</code> 记 <code>event=fail</code> <code>reason=timeout</code> 与 <code>duration_ms</code>, 结算命令与掉落照常执行), 玩家送回进入前位置, 实例按 <code>fail:timeout</code> 销毁回收; 不触发 <code>DungeonCompleteEvent</code>, 不计入排行榜</td></tr><tr><td><code>enter.prepare-window-seconds</code></td><td>int</td><td><code>10</code></td><td><code>&gt;= 1</code></td><td>全员准备确认窗口 (秒), 超时未确认则挑战作废; 小于 1 时该副本加载失败</td></tr><tr><td><code>enter.wait-channel</code></td><td>string</td><td><code>bossbar</code></td><td><code>bossbar</code> / <code>scoreboard</code> / <code>chat</code></td><td>世界准备等待的提示通道; <strong>填其他值会让该副本配置加载失败</strong></td></tr><tr><td><code>enter.wait-timeout-seconds</code></td><td>int</td><td><code>60</code></td><td><code>&gt;= 1</code></td><td>世界准备最长等待 (秒), 超时自动作废; 小于 1 时该副本加载失败</td></tr><tr><td><code>pool.max-worlds</code></td><td>int</td><td><code>5</code></td><td><code>&gt;= 1</code></td><td>该副本实例世界上限 (含补位态), 达上限提示等待重试; 小于 1 时该副本加载失败</td></tr><tr><td><code>pool.warm-reserves</code></td><td>int</td><td><code>2</code></td><td><code>&gt;= 1</code> (小于 1 按 1)</td><td>保持热备的补位世界数 = 活跃实例数 + 该值 (不超过 <code>pool.max-worlds</code>); 建议 2–3, 让克隆/挂载提前于下一次进入完成, 避免补位创建与玩家进入尖峰重叠; 缺省按 2</td></tr></tbody></table><h3 id="limits-挑战限制" tabindex="-1"><code>limits</code> 挑战限制 <a class="header-anchor" href="#limits-挑战限制" aria-label="Permalink to “limits 挑战限制”">​</a></h3><p>判定顺序固定为 <strong>月 &gt; 周 &gt; 日</strong>: 任一层不满足或次数耗尽就不可进入, 后面的层级不再判定. <code>count</code> 为 <code>0</code> 表示该层不限次数, 负数会被按 <code>0</code> 处理</p><table tabindex="0"><thead><tr><th>字段</th><th>类型</th><th>默认值</th><th>取值范围</th><th>说明</th></tr></thead><tbody><tr><td><code>limits.daily.count</code></td><td>int</td><td><code>1</code></td><td><code>&gt;= 0</code></td><td>每日可挑战次数, <code>0</code> 不限</td></tr><tr><td><code>limits.daily.time-window</code></td><td>string</td><td><code>&quot;&quot;</code></td><td><code>&quot;HH:mm-HH:mm&quot;</code> 或留空</td><td>每日可挑战时段, 支持跨午夜 (如 <code>&quot;23:00-01:00&quot;</code>); 格式不对时该副本加载失败</td></tr><tr><td><code>limits.weekly.count</code></td><td>int</td><td><code>0</code></td><td><code>&gt;= 0</code></td><td>每周可挑战次数</td></tr><tr><td><code>limits.weekly.days</code></td><td>list&lt;int&gt;</td><td><code>[]</code></td><td><code>1</code>–<code>7</code> (1 = 周一)</td><td>允许挑战的周几, 空列表不拦; 写错条目时该副本加载失败</td></tr><tr><td><code>limits.monthly.count</code></td><td>int</td><td><code>0</code></td><td><code>&gt;= 0</code></td><td>每月可挑战次数</td></tr><tr><td><code>limits.monthly.weeks</code></td><td>list&lt;int&gt;</td><td><code>[]</code></td><td><code>1</code>–<code>6</code></td><td>允许挑战的月周次 (周一起始), 空列表不拦; 写错条目时该副本加载失败</td></tr><tr><td><code>limits.cooldown-seconds</code></td><td>int</td><td><code>0</code></td><td><code>&gt;= 0</code></td><td>每次进入后的冷却秒数, 负数按 0 处理</td></tr></tbody></table><h3 id="world-与-difficulty" tabindex="-1"><code>world</code> 与 <code>difficulty</code> <a class="header-anchor" href="#world-与-difficulty" aria-label="Permalink to “world 与 difficulty”">​</a></h3><table tabindex="0"><thead><tr><th>字段</th><th>类型</th><th>默认值</th><th>取值范围</th><th>说明</th></tr></thead><tbody><tr><td><code>world.simulation-distance</code></td><td>int</td><td><code>6</code></td><td><code>—</code></td><td>每个实例世界独立生效的仿真距离</td></tr><tr><td><code>world.entity-limit</code></td><td>int</td><td><code>0</code></td><td><code>—</code></td><td>实例世界实体上限, <code>0</code> 不限</td></tr><tr><td><code>difficulty.&lt;档名&gt;.mob-multiplier</code></td><td>double</td><td><code>1.0</code> (normal)</td><td><code>&gt;= 0</code></td><td>怪物属性倍率, 负数按 0 处理</td></tr><tr><td><code>difficulty.&lt;档名&gt;.drop-multiplier</code></td><td>double</td><td><code>1.0</code> (normal)</td><td><code>&gt;= 0</code></td><td>掉落数量倍率, 负数按 0 处理</td></tr><tr><td><code>difficulty.&lt;档名&gt;.respawn-count</code></td><td>int</td><td><code>3</code> (normal)</td><td><code>—</code></td><td>玩家剩余重生次数, 用尽转入观战</td></tr></tbody></table><p>模板默认提供 <code>normal</code> 与 <code>hard</code> 两档 (<code>hard</code> 为 <code>1.5</code> / <code>1.2</code> / <code>1</code>), 玩家在进入流程的难度面板里选择; 你把 <code>difficulty</code> 段清空时按默认两档处理, 也可以自行增删档名</p><h3 id="score-评分与-drop-掉落" tabindex="-1"><code>score</code> 评分与 <code>drop</code> 掉落 <a class="header-anchor" href="#score-评分与-drop-掉落" aria-label="Permalink to “score 评分与 drop 掉落”">​</a></h3><table tabindex="0"><thead><tr><th>字段</th><th>类型</th><th>默认值</th><th>取值范围</th><th>说明</th></tr></thead><tbody><tr><td><code>score.damage-weight</code></td><td>double</td><td><code>1.0</code></td><td><code>—</code></td><td>伤害贡献权重</td></tr><tr><td><code>score.kill-weight</code></td><td>double</td><td><code>1.0</code></td><td><code>—</code></td><td>击杀贡献权重</td></tr><tr><td><code>score.heal-weight</code></td><td>double</td><td><code>1.0</code></td><td><code>—</code></td><td>治疗贡献权重</td></tr><tr><td><code>score.death-weight</code></td><td>double</td><td><code>1.0</code></td><td><code>—</code></td><td>死亡贡献权重</td></tr><tr><td><code>score.defense-weight</code></td><td>double</td><td><code>1.0</code></td><td><code>—</code></td><td>承伤/防守贡献权重</td></tr><tr><td><code>score.max</code></td><td>double</td><td><code>100.0</code></td><td><code>&lt;= 0</code> 时回退默认</td><td>评分满分 (完成时间权重暂不计入); 填 0 或负数会静默回退为默认 100</td></tr><tr><td><code>drop.levels</code></td><td>map</td><td><code>common: 1</code>, <code>rare: 3</code>, <code>epic: 5</code></td><td>整数, 小于 1 按 1</td><td>掉落等级权重, 仅评分贡献分配模式下参与分配</td></tr><tr><td><code>drop.default-mode</code></td><td>string</td><td><code>free</code></td><td>见 <code>mode-allowed</code></td><td>默认掉落分配模式, 填了无效模式会回退为 <code>free</code></td></tr><tr><td><code>drop.mode-allowed</code></td><td>list&lt;string&gt;</td><td><code>[free, roll, killer, score, share]</code></td><td>五种模式的子集</td><td>队长在分配模式面板里可选的模式集合; 无效条目被剔除, 全部无效则用默认五种</td></tr></tbody></table><p>五种分配模式: <code>free</code> 自由拾取暂存, <code>roll</code> 自动 ROLL 分配, <code>killer</code> 归击杀者, <code>score</code> 按评分贡献分配, <code>share</code> 全队平分; 你在 <code>drop.mode-allowed</code> 里决定面板上开放哪几种</p><h3 id="其余副本级配置" tabindex="-1">其余副本级配置 <a class="header-anchor" href="#其余副本级配置" aria-label="Permalink to “其余副本级配置”">​</a></h3><table tabindex="0"><thead><tr><th>字段</th><th>类型</th><th>默认值</th><th>取值范围</th><th>说明</th></tr></thead><tbody><tr><td><code>commands.allow</code></td><td>list&lt;string&gt;</td><td><code>[]</code></td><td>同全局 <code>commands.rules</code> 写法</td><td>本副本额外放行的命令; 可豁免常规管控, <strong>不可豁免逃逸黑名单</strong></td></tr><tr><td><code>interaction.containers</code></td><td>boolean</td><td><code>true</code></td><td><code>true</code> / <code>false</code></td><td>副本内是否允许开箱子等容器交互</td></tr><tr><td><code>interaction.hoppers</code></td><td>boolean</td><td><code>false</code></td><td><code>true</code> / <code>false</code></td><td>是否允许漏斗行为, 默认关闭</td></tr><tr><td><code>timer.messages</code></td><td>list&lt;int&gt;</td><td><code>[300, 60, 10]</code></td><td>秒数列表</td><td>剩余时间倒计时提醒档位, 触发时给玩家发&quot;剩余 N 秒&quot;</td></tr><tr><td><code>settlement.commands</code></td><td>list&lt;string&gt;</td><td><code>[]</code></td><td>控制台命令行</td><td>通关结算时逐条执行的命令, 可用 <code>%player%</code> 占位, 调 EmakiItem/EmakiLevel 发奖</td></tr><tr><td><code>leaderboard.max-entries</code></td><td>int</td><td><code>100</code></td><td><code>&lt; 1</code> 回退 100</td><td>排行榜保留条数, 超限淘汰最差记录; 填 0 或负数会回退默认 100</td></tr></tbody></table><h2 id="奖励箱界面-gui-rewardbox-yml" tabindex="-1">奖励箱界面 <code>gui/rewardbox.yml</code> <a class="header-anchor" href="#奖励箱界面-gui-rewardbox-yml" aria-label="Permalink to “奖励箱界面 gui/rewardbox.yml”">​</a></h2><p>这个界面的布局结构固定, 不可配置, 只开放两个数值:</p><table tabindex="0"><thead><tr><th>字段</th><th>类型</th><th>默认值</th><th>取值范围</th><th>说明</th></tr></thead><tbody><tr><td><code>default-pages</code></td><td>int</td><td><code>1</code></td><td><code>—</code></td><td>玩家没有更高页数权限时的基础可见页数</td></tr><tr><td><code>capacity-slots</code></td><td>int</td><td><code>135</code></td><td><code>—</code></td><td>奖励箱总容量 (物品格总数), 达到即视为箱满; 满箱规则见 <a href="./challenges.html#奖励箱与领取">挑战与奖励</a></td></tr></tbody></table><h2 id="流程文件-world-副本id-flow-yml" tabindex="-1">流程文件 <code>world/&lt;副本ID&gt;/flow.yml</code> <a class="header-anchor" href="#流程文件-world-副本id-flow-yml" aria-label="Permalink to “流程文件 world/&lt;副本ID&gt;/flow.yml”">​</a></h2><p>这个文件承载房间, 波次, 门禁, 选项等全部流程模块, 缺失时插件会自动生成; 完整结构见 <a href="./flow.html">流程与触发器</a></p>`,41)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};